INSERT INTO places (id, name, description, image_url, location, category, website_url, latitude, longitude) VALUES
('37d96e8b-6d00-4a65-8297-2af31ca42765', 'حديقة الأمير سلطان بن سلمان', 'تعد أحد أفضل المنتزهات في الباحة، وتتميز بتصميم فريد وبها مرافق وخدمات متنوعة وأنشطة مختلفة تمكنك من قضاء وقت ممتع برفقة العائلة', '@assets/حديقة الامير سلطان_1757970030009.jpg', 'مدينة الباحة', 'حديقة', NULL, NULL, NULL),
('052dd3a9-3f47-4910-b20e-1dabbf99a796', 'حديقة اللافندر', 'تمثل حديقة اللافندر أحد أهم المواقع السياحية البارزة في منطقة الباحة لما تحتويه من جمال طبيعي، فضلاً عن الموقع المتميز وسط غابة رغدان مما يجعلها منتجعاً سياحياً ومقصداً للأهالي والزوار من محبي الاستمتاع بسحر الطبيعة', '@assets/حديقة الافندر_1758387560441.jpg', 'مدينة الباحة', 'حديقة', NULL, NULL, NULL),
('fe09c2e1-0140-4321-882a-432561a361bb', 'منتزه الدانة', 'يتيح المنتزه للزائرين فرصة قضاء وقت مميز عبر التجول خلال المسطحات الخضراء والاستمتاع بالفعاليات المتنوعة والأنشطة الترفيهية، كما توفر مناطق للراحة مظللة تتيح للزوار الجلوس والإسترخاء', '@assets/منتزه الدانه_1758387560443.jpg', 'محافظة بلجرشي', 'منتزه', NULL, NULL, NULL),
('c316dad0-4a40-4d97-88a6-74ee57f3c194', 'مطعم مشراق', 'مطعم', '/assets/___________1759000318853_Ecsa5AW3.jpeg', NULL, 'مطعم', NULL, NULL, NULL),
('4f6041e0-d7e6-4b63-a1b5-bee3862c66f2', 'القرية الأثرية بالأطاولة', 'قريه تراثيه', NULL, 'القرى.الباحة', 'قرى', 'https://maps.app.goo.gl/waY64knwYhXdC6K89', '20.249999', '41.359802'),
('73f539ff-ef74-42aa-a0a4-057d1c7e0556', 'منتزه سد الجنابين', 'يستقطب منتزه سد وادي الجنابين في محافظة بلجرشي العديد من الزوار والمتنزهين لمشاهدة بحيرة السد والتقاط الصور خلال الاستمتاع بتكوينات المنتزه الجغرافية التي تحتضن مناطق تجميع المياه الطبيعية', '@assets/منتزه سد الجنابين_1758387560444.jpg', 'محافظة بلجرشي', 'منتزه', NULL, NULL, NULL),
('bd3289be-84b0-43b5-ae9d-01222134fef4', 'منتزه الشروق', 'يمثل منتزه الشروق أحد المواقع السياحية البارزة في منطقة الباحة لما يحتويه من جمال طبيعي، فضلاً عن الموقع المتميز الذي يشكل منتجعاً سياحياً ومقصداً للأهالي والزوار من محبي الاستمتاع بالطبيعة', '@assets/منتزه الشروق_1758387560443.jpg', 'محافظة العقيق', 'منتزه', NULL, NULL, NULL),
('69ff1c51-ce97-47fc-9f11-64e735c47e75', 'منتزه الشلال', 'يتوسط المنتزه موقع متميز وسط جمال الطبيعة ويضم مجموعة من الخدمات والمرافق اللازمة لخدمة الزوار كما يحتوي على جلسات مظللة وممرات للمشاة وألعاب أطفال ويتميز بشلالات وبحيرات مائية', '@assets/منتزه الشلال_1758387560443.jpg', 'محافظة بني حسن', 'منتزه', NULL, NULL, NULL),
('617dc9e7-6aa8-4ba1-9725-28708d635816', 'شلال صفا البراق', 'من أجمل الشلالات في منطقة الباحة، يتميز بتدفق المياه الصافية من ارتفاعات عالية وسط المناظر الطبيعية الخلابة', '@assets/شلال صفا البراق_1758387560442.jpg', 'مدينة الباحة', 'شلال', NULL, NULL, NULL),
('79833d74-7800-45a4-9ddb-c5864f0d2a16', 'شلال أم الدقيق', 'شلال طبيعي جميل يقع في منطقة جبلية ساحرة، يجذب الزوار بصوت المياه المتدفقة والمناظر الطبيعية المحيطة', '@assets/شلال ام الدقيق_1758387560442.jpg', 'مدينة الباحة', 'شلال', NULL, NULL, NULL),
('7b6780c8-712f-4fe5-8303-1a0fbb558811', 'شلال الغدير', 'شلال رائع يتدفق في منطقة خضراء جميلة، يوفر أجواء هادئة ومنعشة للزوار والمتنزهين', '@assets/شلال الغدير_1758387560442.jpg', 'مدينة الباحة', 'شلال', NULL, NULL, NULL),
('3d16d397-8314-443b-bdfb-eb84ec03ac71', 'فيفث سيزون', 'مطعم', '/assets/____________________1759000743656_Rb5WQv9G.jpeg', NULL, 'مطعم', NULL, NULL, NULL),
('a2c90f22-5977-4b10-acb1-c62fc3034fbc', 'وادي ثراد', 'من أشهر وديان منطقة الباحة في محافظة العقيق، بالإضافة إلى موقعه الجاذب', '@assets/وادي ثراد_1758387560445.jpg', 'محافظة العقيق', 'وادي', NULL, NULL, NULL),
('fc13c5fd-f8a1-448b-8368-28ff8d86d7a6', 'منتزه الخلب', 'يقع على ربوة عالية بإطلالات واسعة على المحافظة والأودية والجبال المجاورة، كما يحتوي على تقسيمات من المسطحات الخضراء بالإضافة إلى ممرات للمشي وشلالات ومجرى للمياه بمنتصف المنتزه مما يضفي جمالية ساحرة وتجربة فريدة', '@assets/منتزه الخلب_1758387560443.jpg', 'محافظة المندق', 'منتزه', NULL, NULL, NULL),
('d4651c7a-6e3b-4003-b92f-76c786087343', 'نزل العائد التراثي', 'يعكس تراث المنطقة وتاريخها ومظاهر الكرم والضيافة كما يعرض مجموعة من أهم القطع الأثرية والأدوات القديمة', '@assets/نزل العائد التراثي_1758387560444.jpg', 'بني كبير', 'تراث', NULL, NULL, NULL),
('2a59d04c-f3f4-454e-8e3a-c2a01c772bdf', 'متحف الأخوين', 'يحتوي المتحف على قطع تمثل مختلف جوانب الحياة في الماضي من الأدوات المنزلية وأدوات الزراعة والصناعة والزينة والسفر وأنواع الأسلحة وغيرها', '@assets/متحف الاخوين_1758387560443.jpg', 'مدينة الباحة', 'متحف', NULL, NULL, NULL),
('b70ed881-a99b-4140-808f-5c6b4c4ca14e', 'قرية ذي عين الأثرية', 'سميت القرية بـ"ذي عين" نسبة لعين الماء التي تنساب من الجبال المجاورة بدون انقطاع، وتتميز القرية بشكلها الجميل، وتعتبر من الوجهات السياحية الرائعة التي تجذب العديد من الزائرين لزيارتها، والاستمتاع بمنظر القرية المهيب', '@assets/ذي عين_1757793151104.jpg', 'محافظة المخواة', 'تراث', NULL, NULL, NULL),
('7bd0bc08-717f-4f5e-b8ae-3466e0b235f4', 'غابة رغدان', 'تعد غابة رغدان إحدى الوجهات المميزة بالمنطقة نظراً لما تتمتع به من مساحات خضراء وطبيعة ساحرة، كما يتخللها العديد من الممرات المكسوة بالحجر التي تتيح للزائر الاستمتاع بالطبيعة الخلابة، إضافة إلى المرافق والأنشطة الترفيهية', '@assets/رغدان_1757793151105.jpg', 'مدينة الباحة', 'غابة', NULL, NULL, NULL),
('d40580a0-a49c-4692-af0c-a4f6368d2c12', 'قلعة بخروش بن علاس', 'قلعة بخروش بن علاس هي إحدى المعالم التاريخية التي تظهر بها تفاصيل القلاع التاريخية الحربية المحصنة، وهي موقع يشعرك بالماضي الجميل الذي عاشه الآباء والأجداد. وتعد قلعة بخروش بن علاس من أبرز القلاع الضخمة المحصنة ويمتد عمرها لأكثر من 200 عام', '@assets/قلعه بخروش_1757793151107.jpg', 'محافظة القرى', 'تراث', NULL, NULL, NULL),
('e85bf22a-be3d-4d69-a03c-73b3ed1b10a7', 'منتزه الأمير حسام', 'جمع منتزه الأمير حسام بين جمال الطبيعة وروعة التصميم، إذ توزعت البحيرات الصناعية والشلالات والنوافير التفاعلية في أرجاء المنتزه، كما زين المنتزه بالمسطحات الخضراء والأشجار والورود', '@assets/منتزه الامير حسام_1757793151107.jpg', 'مدينة الباحة', 'منتزه', NULL, NULL, NULL),
('9fa6b945-08d0-4a16-9d0f-4276ffecb6ef', 'سد وادي العقيق', 'أكبر سد بالمنطقة ويوجد به كميات كبيرة من مخزون المياه الذي يستخدمه أهالي منطقة الباحة', '@assets/سد وادي العقيق_1757970030010.jpg', 'محافظة العقيق', 'سد', NULL, NULL, NULL),
('80f64067-2897-47ca-b395-f91dc835e946', 'وادي القدحة بمسير', 'من أشهر وديان منطقة الباحة في محافظة العقيق، بالإضافة إلى موقعه المتميز', '@assets/وادي القدحة_1758387560444.jpg', 'محافظة المندق', 'وادي', NULL, NULL, NULL),
('5b6f5cfc-d581-4c2e-b69d-a10cb6aeb827', 'وادي تربة زهران', 'يعتبر وادي تربة أحد أكبر أودية الجزيرة العربية، يبلغ طوله أكثر من 330 كم', '@assets/وادي تربه زهران_1758387560444.jpg', 'محافظة المندق', 'وادي', NULL, NULL, NULL),
('d33684ce-2f2c-42c6-b526-cdc47a3aac57', 'شلال الشولة', 'شلال طبيعي في محافظة بني حسن، يقع وسط منطقة جبلية خضراء جميلة', '@assets/شلال الشوله11_1758387560442.jpg', 'محافظة بني حسن', 'شلال', NULL, NULL, NULL),
('1279be38-9752-4794-a486-f3b821713b93', 'شلال الشراشير', 'شلال جميل يقع في محافظة بني حسن، يتدفق من ارتفاعات عالية وسط الطبيعة الساحرة', '@assets/شلال الشراشير_1758387560442.jpg', 'محافظة بني حسن', 'شلال', NULL, NULL, NULL),
('72335b4f-57c0-4c8a-9f2d-8e6864a75588', 'شلال الحمده', 'من الشلالات الجميلة في منطقة الباحة، يتميز بالمياه المتدفقة والطبيعة الخلابة المحيطة', '@assets/شلال الحمده_1757793151105.jpg', 'مدينة الباحة', 'شلال', NULL, NULL, NULL),
('96b7d16d-e231-4ca1-a89c-86c745513a41', 'شلال خيرة', 'يقع في غابة خيرة، شلال طبيعي متدفق وسط الصخور والنباتات الكثيفة، يضفي جمالية خاصة على المكان', '@assets/شلال خيره_1757793151106.jpg', 'محافظة بني حسن', 'شلال', NULL, NULL, NULL),
('a20d6a69-f477-4929-bbb2-2d18cc685f43', 'شلال عين الجمل', 'من الشلالات المميزة في محافظة بني حسن، يحاط بالنباتات الطبيعية والصخور', '@assets/شلال عين الجمل_1757793151106.jpg', 'محافظة بني حسن', 'شلال', NULL, NULL, NULL),
('7a3f9688-f929-41f3-9863-bdaa89b84d86', 'غابة خيرة', 'واحدة من أجمل المناطق السياحية في منطقة الباحة وداُماً ما تفتح أبوابها لعشاق الطبيعة والمناظر الخلابة لما تحتويه من محاطة بغطاء نباتي وأشجار كثيفة وشلالات متدفقة وبرك مياه محاطة بتشكيلات صخرية خلابة', '@assets/غابة خيره_1757793151107.jpg', 'محافظة بني حسن', 'غابة', NULL, NULL, NULL),
('1919ccc0-60a2-4e6f-9148-857a29f78757', 'فندق الشهبة انترنشونال', 'فندق مميز في الباحة', '/assets/___________________________________________1758999921687_xyjHjwzw.jpeg', NULL, 'فندق', NULL, NULL, NULL),
('9885ff87-9664-4f5f-aba5-8455be77bad3', 'فندق السحاب', 'فندق مميز في الباحة', '/assets/______________________1759000014147_3kMAoIq1.jpeg', NULL, 'فندق', NULL, NULL, NULL),
('93b12594-d6a4-475f-9f67-31b99fd67746', 'فندق الفاضل', 'فندق مميز في الباحة', '/assets/______________________1759000091099_8YvynSMG.jpeg', NULL, 'فندق', NULL, NULL, NULL),
('63fdfed1-e320-41c5-9b4a-e78558f15650', 'مطعم ومقهى سول', 'مطعم', '/assets/_______1759000205698_eNMWGTED.jpeg', NULL, 'مطعم', NULL, NULL, NULL);
