INSERT INTO team_members (id, name, role, description, image_url, order_index, is_active) VALUES
('111fa3f5-96c7-497e-9968-c821f078965b', 'احمد الغامدي', 'طالب جامعي', 'طالب خريج، وساهمت في مشروع التخرج لإنشاء هذا الموقع لدعم السياحة في منطقتنا وتسليط الضوء على الأماكن السياحية المهمة.', '/assets/IMG_6620_1758390733686_0yzVkqTG.jpeg', 0, true),
('e6904e22-9042-4255-8744-fd9100b24d4c', 'سعد نايف خميس الزهراني', 'طالب جامعي', 'طالب خريج، وساهمت في مشروع التخرج لإنشاء هذا الموقع لدعم السياحة في منطقتنا وتسليط الضوء على الأماكن السياحية المهمة.', '/assets/1000107569_1758430835178_46WQa0fN.jpeg', 0, true),
('9b1548ca-a9b5-4b1d-80e9-a3dbc84b1587', 'مبارك الغامدي', 'طالب جامعي', 'طالب خريج، وساهمت في مشروع التخرج لإنشاء هذا الموقع لدعم السياحة في منطقتنا وتسليط الضوء على الأماكن السياحية المهمة.', '/assets/IMG_0710_1758990975044_Fx4b_hFX.jpeg', 0, true),
('67e89a58-0aa3-4f94-9ebd-2de053457206', 'مشاري سلطان الزهراني', 'طالب جامعي', 'طالب خريج، وساهمت في مشروع التخرج لإنشاء هذا الموقع لدعم السياحة في منطقتنا وتسليط الضوء على الأماكن السياحية المهمة.', '/assets/_______1758390670963_ehTZCFSI.jpg', 0, true),
('f7dd6fe7-1968-4464-ad12-7f68b2853f86', 'نواف محمد الغامدي', 'طالب جامعي', 'طالب خريج، وساهمت في مشروع التخرج لإنشاء هذا الموقع لدعم السياحة في منطقتنا وتسليط الضوء على الأماكن السياحية المهمة.', '/assets/IMG_2369_1759002266166_PYYt54R9.png', 0, true);
INSERT INTO site_content (id, key, title, content, updated_by) VALUES
('fba0a210-07f8-43e9-94d2-753e6b5ed569', 'about_us', 'نبذة عنا', 'منصة الباحة السياحية هي منصة رقمية مبتكرة تهدف إلى الربط بين السياح والمرشدين السياحيين المحليين في منطقة الباحة الخلابة بالمملكة العربية السعودية.
